# Conversion helpers never modify the original input text.
import re


def convert_text_value(text, mode):
    # Whole Unicode words are used for the simple camelCase transformation.
    if mode == "upper":
        return text.upper()
    if mode == "lower":
        return text.lower()
    if mode == "camel":
        words = re.findall(r"[^\W_]+", text, flags=re.UNICODE)
        return words[0].lower() + "".join(word.title() for word in words[1:]) if words else ""
    if mode == "markdown":
        return "\n".join("- " + line.strip() for line in text.splitlines() if line.strip())
    raise ValueError("Unknown conversion mode")


def text_update_stats(app):
    # Tk Text adds a final newline; exclude it from the user's character count.
    text = app.InputText.get("1.0", "end-1c")
    app.StatsLabel.configure(text=f"Words: {len(text.split())} | Characters: {len(text)}")


def text_convert(app, mode):
    text = app.InputText.get("1.0", "end-1c")
    app.OutputText.delete("1.0", "end")
    app.OutputText.insert("1.0", convert_text_value(text, mode))
    text_update_stats(app)
